117:   async cargarTodasSolicitudes() {
118:     this.listaDatos = [];
119:     try {
120:       await Promise.all([
121:         this.cargarSolicitudPorTipo(15),
122:         this.cargarSolicitudPorTipo(16),
123:         this.cargarSolicitudPorTipo(17),
124:         this.cargarSolicitudPorTipo(18),
125:         this.cargarSolicitudPorTipo(19),
126:         this.cargarSolicitudPorTipo(20),
127:         this.cargarSolicitudPorTipo(32),
128:         this.cargarSolicitudPorTipo(33),
