137:   cargarSolicitudPorTipo(IdEstadoTipoSolicitud: number): Promise<void> {
138:     return new Promise((resolve, reject) => {
139:       this.sgaMidActualizacionDatosService
140:         .get(`solicitudes/estados/${IdEstadoTipoSolicitud}`)
141:         .subscribe(
142:           (response: any) => {
143:             if (response.Status === 200 && response.Success === true) {
144:               const data = response.Data.Data;
145:               const dataInfo = data.map((element: any) => {
146:                 element.Fecha = momentTimezone
147:                   .tz(element.Fecha, 'America/Bogota')
148:                   .format('DD/MM/YYYY');
149:                 return element;
150:               });
151:               this.listaDatos.push(dataInfo);
152:               resolve();
153:             } else {
154:               resolve();
155:             }
156:           },
157:           (error) => {
158:             this.popUpManager.showErrorToast(
159:               this.translate.instant('ERROR.general')
160:             );
161:             reject(error);
162:           }
163:         );
164:     });
165:   }
166: 
167:   async cargarSolicitudPorIdTercero() {
168:     try {
169:       const IdTercero = await this.userService.getPersonaId();
170:       this.sgaMidActualizacionDatosService
171:         .get(`solicitudes/estudiantes/${IdTercero}`)
172:         .subscribe(
173:           (response: any) => {
174:             if (response.Status === 200) {
175:               const data = response.Data.Response;
176:               const dataInfo = data.map((element: any) => {
177:                 element.Fecha = momentTimezone
178:                   .tz(element.Fecha, 'America/Bogota')
179:                   .format('DD/MM/YYYY');
180:                 return element;
181:               });
182:               this.cargarDatosTabla(dataInfo);
183:             } else {
184:               this.popUpManager.showInfoToast(
185:                 'info',
186:                 this.translate.instant('solicitudes.no_data')
187:               );
188:             }
189:           },
190:           () => {
191:             this.popUpManager.showErrorToast(
192:               this.translate.instant('ERROR.general')
193:             );
194:           }
195:         );
196:     } catch (error) {
197:       this.popUpManager.showErrorToast(
198:         this.translate.instant('ERROR.general') + error
199:       );
200:     }
