22: @Component({
23:     selector: "app-modal-rechazo-auditoria",
24:     templateUrl: "./modal-rechazo-auditoria.component.html",
25:     standalone: false
26: })
27: export class ModalRechazoAuditoriaComponent implements OnInit {
28:   formObservaciones!: FormGroup;
29: 
30:   constructor(
31:     @Inject(MAT_DIALOG_DATA) public infoModal: any,
32:     public readonly dialogRef: MatDialogRef<ModalMotivosRechazoComponent>,
33:     private readonly alertService: AlertService,
34:     private readonly fb: FormBuilder,
35:     private readonly planAuditoriaService: PlanAnualAuditoriaService,
36:     private readonly router: Router,
37:     private readonly tercerosService: TercerosService,
38:     private readonly notificacionesService: NotificacionesService,
39:     private readonly notificacionRegistroCrudService: NotificacionRegistroCrudService,
40:     private readonly parametrosUtilsService: ParametrosUtilsService,
41:   ) {}
42: 
43:   ngOnInit() {
44:     this.iniciarFormObservaciones();
45:   }
46: 
47:   iniciarFormObservaciones() {
48:     this.formObservaciones = this.fb.group({
49:       observaciones: ["", Validators.required],
50:     });
51:   }
52: 
53:   preguntarConfirmacionRechazo() {
54:     if (this.formObservaciones.invalid) {
55:       this.alertService.showErrorAlert("Debe ingresar una observación.");
56:       return;
57:     }
58: 
59:     this.alertService
60:       .showConfirmAlert("¿Está seguro de rechazar la Auditoría?")
61:       .then((confirmado) => {
62:         if (!confirmado.value) {
63:           return;
64:         }
65:         this.rechazarPlanAuditoria();
66:       });
67:   }
68: 
69:   rechazarPlanAuditoria() {
70:     const auditoriaEstado = this.construirObjetoAuditoriaEstado();
71:     this.planAuditoriaService
72:       .post("auditoria-estado", auditoriaEstado)
73:       .subscribe({
74:         next: () => {
75:           this.alertService.showSuccessAlert(
76:             "Auditoría rechazada",
77:             "La auditoría fue devuelta al auditor(a)."
78:           ).then(() => {
79:             this.notificarRechazo(this.infoModal.auditoriaId);
80:             this.dialogRef.close();
81:             this.router.navigate([`/planeacion/auditorias-internas/`]);
82:           });
83:         },
84:         error: (error) => {
85:           this.alertService.showErrorAlert(
86:             "Error al asociar el nuevo estado a la auditoría."
87:           );
88:           console.error(error);
89:         }
90:       });
91:   }
92: 
93:   construirObjetoAuditoriaEstado() {
94:     return {
95:       auditoria_id: this.infoModal.auditoriaId,
96:       usuario_id: this.infoModal.usuarioId,
97:       usuario_rol: this.infoModal.role,
98:       observacion: this.formObservaciones.get("observaciones")?.value,
99:       estado_id: environment.AUDITORIA_ESTADO.PLANEACION.RECHAZADO_PROGRAMA_JEFE,
100:       fase_id: environment.AUDITORIA_FASE.PLANEACION,
101:     };
102:   }
103: 
104:   /**
105:    * Notifica a los auditores asignados cuando el Jefe OCI o el auditado
106:    * rechaza el programa de auditoría.
107:    */
108:   /**
109:    * Notifica a los auditores asignados cuando el Jefe OCI o el auditado rechaza
110:    * el programa de auditoría.
111:    * Sigue el patrón de consulta-plan-auditoria: resuelve Terceros primero y sola,
112:    * luego encadena las demás consultas.
113:    */
114:   private notificarRechazo(auditoriaId: string): void {
115:     const role = this.infoModal.role;
116:     const roleLabels: Record<string, string> = {
117:       [environment.ROL.JEFE]: "Jefe OCI",
118:       [environment.ROL.JEFE_DEPENDENCIA]: "Jefe de Dependencia",
119:       [environment.ROL.ASISTENTE_DEPENDENCIA]: "Asistente de Dependencia",
120:     };
121: 
122:     const rolRemitente = roleLabels[role] ?? role ?? "Revisor";
123: 
124:     this.tercerosService.getAuthenticatedUserTerceroIdentification().pipe(
125: 
126:       exhaustMap((tercero) => {
127:         console.log("Tercero autenticado:", tercero.NombreCompleto);
128:         return forkJoin({
129:           auditoria: this.planAuditoriaService.get(`auditoria/${auditoriaId}`),
130:           auditores: this.planAuditoriaService.get(
131:             `auditor?query=auditoria_id:${auditoriaId},asignado:true,activo:true&limit=0`
132:           ),
133:           vigencias: this.parametrosUtilsService.getVigencias(),
134:           nombreRemitente: of(tercero.NombreCompleto),
135:         });
136:       }),
137: 
138:       exhaustMap(({ auditoria, auditores, vigencias, nombreRemitente }: any) => {
139:         const datosAuditoria: Auditoria = auditoria?.Data;
140:         const listaAuditores: any[] = auditores?.Data ?? [];
141: 
142:         // Resolver vigencia igual que el PAA — desde ParametrosUtilsService
143:         const vigenciaId = datosAuditoria?.vigencia_id;
144:         const vigenciaObj = vigencias.find((v: any) => v.Id === vigenciaId);
145:         const vigenciaNombre = vigenciaObj?.Nombre || (vigenciaId ? String(vigenciaId) : "");
146: 
147:         console.log("auditoria_id:", auditoriaId);
148:         console.log("titulo auditoria:", datosAuditoria?.titulo);
149:         console.log("vigencia_id:", vigenciaId);
150:         console.log("vigencia_nombre resuelta:", vigenciaNombre);
151:         console.log("auditores encontrados:", listaAuditores.length);
152:         console.log("auditores:", listaAuditores.map((a: any) => a.auditor_id));
153: 
154:         const correosAuditores$ = listaAuditores.length > 0
155:           ? forkJoin(
156:               listaAuditores.map((a: any) =>
157:                 this.tercerosService.getTerceroById(a.auditor_id).pipe(
158:                   catchError(() => of(null))
159:                 )
160:               )
161:             )
162:           : of([]);
163: 
164:         return correosAuditores$.pipe(
165:           switchMap((terceros: any[]) => {
166:             const correosAuditores = terceros
167:               .filter((t) => t?.UsuarioWSO2)
168:               .map((t) => t.UsuarioWSO2)
169:               .filter((v: string) => v.includes('@'));
170: 
171:             console.log("correos auditores resueltos:", correosAuditores);
172: 
173:             if (correosAuditores.length === 0) {
174:               console.warn("No se encontraron correos de auditores — se notifica solo al environment.");
175:             }
176: 
177:             const fijosRechazo = role === environment.ROL.JEFE
178:               ? environment.NOTIFICACION_PROGRAMA_TRABAJO_RECHAZO_JEFE_DESTINATARIOS
179:               : environment.NOTIFICACION_PROGRAMA_TRABAJO_RECHAZO_AUDITADO_DESTINATARIOS;
180: 
181:             console.log("constante de environment seleccionada:", role === environment.ROL.JEFE
182:               ? "RECHAZO_JEFE_DESTINATARIOS"
183:               : "RECHAZO_AUDITADO_DESTINATARIOS"
184:             );
185: 
186:             const destinatarios: DestinatariosEmail = {
187:               ToAddresses: [
188:                 ...correosAuditores,
189:                 ...(fijosRechazo.ToAddresses ?? []),
190:               ],
191:               CcAddresses: fijosRechazo.CcAddresses ?? [],
192:               BccAddresses: fijosRechazo.BccAddresses ?? [],
193:             };
194: 
195:             const variablesRechazo: VariablesRechazo = {
196:               titulo_rechazo: "Rechazo de Programa de Auditoría",
197:               motivo_rechazo: this.formObservaciones.get("observaciones")?.value ?? '',
198:               nombre_documento: `Programa de Auditoría${datosAuditoria?.titulo ? ' - ' + datosAuditoria.titulo : ''}`,
199:               vigencia: vigenciaNombre,
200:               rol_remitente: rolRemitente,
